import { deflateSync } from "node:zlib";

function chunk(kind: string, data: Uint8Array): Buffer {
  const header = Buffer.alloc(8);
  header.writeUInt32BE(data.length);
  header.write(kind, 4);
  return Buffer.concat([header, data, Buffer.alloc(4)]);
}

/** Synthetic carrier containing generated bytes, never a captured provider segment. */
export function sportsPng(
  payload: Uint8Array,
  marker = "KWP1",
  filter = 0,
): Uint8Array {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(payload.length);
  const envelope = Buffer.concat([Buffer.from(marker), length, payload]);
  const width = Math.ceil(envelope.length / 3);
  const pixels = Buffer.alloc(width * 3);
  pixels.set(envelope);
  const filtered = Buffer.alloc(pixels.length + 1);
  filtered[0] = filter;
  for (let index = 0; index < pixels.length; index++) {
    const left = index >= 3 ? (pixels[index - 3] ?? 0) : 0;
    const prediction =
      filter === 1 || filter === 4
        ? left
        : filter === 3
          ? Math.floor(left / 2)
          : 0;
    filtered[index + 1] = ((pixels[index] ?? 0) - prediction) & 255;
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width);
  ihdr.writeUInt32BE(1, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(filtered)),
    chunk("IEND", new Uint8Array()),
  ]);
}
